import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<String> generateParenthesis(int n) {
        List<String> result = new ArrayList<>();
        generate(new StringBuilder(), 2 * n, result);
        return result;
    }

    private void generate(StringBuilder current, int length, List<String> result) {
        if (current.length() == length) {
            if (isValid(current)) {
                result.add(current.toString());
            }
            return;
        }
        current.append('(');
        generate(current, length, result);
        current.deleteCharAt(current.length() - 1);
        current.append(')');
        generate(current, length, result);
        current.deleteCharAt(current.length() - 1);
    }

    private boolean isValid(StringBuilder candidate) {
        int balance = 0;
        for (int index = 0; index < candidate.length(); index++) {
            balance += candidate.charAt(index) == '(' ? 1 : -1;
            if (balance < 0) {
                return false;
            }
        }
        return balance == 0;
    }
}

