import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<String> generateParenthesis(int n) {
        List<String> result = new ArrayList<>();
        build(n, 0, 0, new StringBuilder(), result);
        return result;
    }

    private void build(int n, int opens, int closes, StringBuilder current, List<String> result) {
        if (current.length() == 2 * n) {
            result.add(current.toString());
            return;
        }
        if (opens < n) {
            current.append('(');
            build(n, opens + 1, closes, current, result);
            current.deleteCharAt(current.length() - 1);
        }
        if (closes < opens) {
            current.append(')');
            build(n, opens, closes + 1, current, result);
            current.deleteCharAt(current.length() - 1);
        }
    }
}
